import org.koin.androidx.compose.koinViewModel

@Composable
fun MainScreen(
 navigateToSetting: () -> Unit,
 viewModel: MainViewModel = koinViewModel(),
 onUpdateTab = { index ->
 viewModel.processIntent(MainIntent.OnTabClick(index))
 }
) {
 val state = viewModel.viewState.collectAsStateWithLifecycle()

 LaunchedEffect(Unit) {
 viewModel.event.collect { event ->
 when (event) {
 MainEvent.NavigateToSetting -> {
 navigateToSetting()
 }
 }
 }
 }

 MainScreenContent(
 state = state.value,
 onTabClick = { index ->
 viewModel.processIntent(MainIntent.OnTabClick(index))
 },
 navigateToSetting = {
 viewModel.processIntent(MainIntent.NavigateToSetting)
 }
 )
}
@Composable
fun MainScreenContent(
 state: MainState,
 navigateToSetting: () -> Unit,
 onTabClick: (Int) -> Unit
) {
 Column(
 modifier = Modifier
 .fillMaxSize()
 .background(color = SoundoraColors.BackGround.BackgroundPrimary)
 .padding(top = WindowInsets.statusBars.asPaddingValues().calculateTopPadding())
 ) {
 MainContent(
 navigateToSetting = {
 navigateToSetting()
 },
 tabSelected = state.tabSelected,
 modifier = Modifier
 .weight(1f)
 )
 NavBar(
 onTabClick = { index ->
 onTabClick(index)
 },
 modifier = Modifier
 .fillMaxWidth(),
 tabSelected = state.tabSelected
 )
 }
}

@Composable
fun MainContent(
 navigateToSetting: () -> Unit,
 modifier: Modifier = Modifier,
 tabSelected: Int = 0
) {
 Column(
 modifier = modifier
 ) {
 when (tabSelected) {
 Constant.MainTabIndex.HOME -> HomeScreen(
 navigateToSetting = {
 navigateToSetting()
 },
 )
 Constant.MainTabIndex.SEARCH -> SearchScreen()
 Constant.MainTabIndex.LIBRARY -> LibraryScreen()
 }
 }
}
